-- Quiz 1: Understanding Bank Accounts
(
    '20000000-0000-4000-8000-000000000001'::uuid, '10000000-0000-4000-8000-000000000001'::uuid,
    jsonb_build_array(
        jsonb_build_object('id', 'q1-1', 'question', 'What is the main benefit of keeping money in a bank account instead of at home?', 'options', jsonb_build_array('It is safe and earns interest', 'It can be stolen easily', 'It loses value over time'), 'correctAnswerIndex', 0, 'explanation', 'Bank accounts are safe, insured up to Rs 5 lakh by DICGC, and earn interest.'),
        jsonb_build_object('id', 'q1-2', 'question', 'Which document is NOT required to open a bank account?', 'options', jsonb_build_array('Aadhaar card', 'PAN card', 'Driving license'), 'correctAnswerIndex', 2, 'explanation', 'Aadhaar, PAN, and address proof are required. A driving license is not mandatory.'),
        jsonb_build_object('id', 'q1-3', 'question', 'What should you do if you lose your ATM card?', 'options', jsonb_build_array('Wait for it to be found', 'Block it immediately through the bank helpline', 'Post about it on social media'), 'correctAnswerIndex', 1, 'explanation', 'Block the card immediately to prevent unauthorized use.')
    ),
    jsonb_build_array(
        jsonb_build_object('id', 'q1-1', 'question', 'ಬ್ಯಾಂಕ್ ಖಾತೆಯಲ್ಲಿ ಹಣ ಇಡುವುದರ ಮುಖ್ಯ ಪ್ರಯೋಜನವೇನು?', 'options', jsonb_build_array('ಸುರಕ್ಷಿತ ಮತ್ತು ಬಡ್ಡಿ ಸಿಗುತ್ತದೆ', 'ಸುಲಭವಾಗಿ ಕಳೆಯಬಹುದು', 'ಕಾಲದೊಂದಿಗೆ ಮೌಲ್ಯ ಕಡಿಮೆಯಾಗುತ್ತದೆ'), 'correctAnswerIndex', 0, 'explanation', 'ಬ್ಯಾಂಕ್ ಖಾತೆಗಳು ಸುರಕ್ಷಿತ, DICGC ಯಿಂದ ರೂ. 5 ಲಕ್ಷ ವರೆಗೆ ವಿಮೆ ರಕ್ಷಣೆ ಮತ್ತು ಬಡ್ಡಿ ನೀಡುತ್ತವೆ.'),
        jsonb_build_object('id', 'q1-2', 'question', 'ಬ್ಯಾಂಕ್ ಖಾತೆ ತೆರೆಯಲು ಯಾವ ದಾಖಲೆ ಅಗತ್ಯವಿಲ್ಲ?', 'options', jsonb_build_array('ಆಧಾರ್ ಕಾರ್ಡ್', 'ಪಾನ್ ಕಾರ್ಡ್', 'ಚಾಲನಾ ಪತ್ರ'), 'correctAnswerIndex', 2, 'explanation', 'ಆಧಾರ್, ಪಾನ್ ಮತ್ತು ವಿಳಾಸ ಪುರಾವೆ ಅಗತ್ಯ. ಚಾಲನಾ ಪತ್ರ ಕಡ್ಡಾಯವಲ್ಲ.'),
        jsonb_build_object('id', 'q1-3', 'question', 'ATM ಕಾರ್ಡ್ ಕಳೆದುಕೊಂಡರೆ ಏನು ಮಾಡಬೇಕು?', 'options', jsonb_build_array('ಸಿಗುವವರೆಗೆ ಕಾಯುವುದು', 'ತಕ್ಷಣ ಬ್ಯಾಂಕ್ ಸಹಾಯವಾಣಿಗೆ ಕರೆ ಮಾಡಿ ನಿರ್ಬಂಧಿಸುವುದು', 'ಸಾಮಾಜಿಕ ಜಾಲತಾಣದಲ್ಲಿ ಪೋಸ್ಟ್ ಮಾಡುವುದು'), 'correctAnswerIndex', 1, 'explanation', 'ಅನಧಿಕೃತ ಬಳಕೆಯನ್ನು ತಡೆಯಲು ತಕ್ಷಣ ಕಾರ್ಡ್ ನಿರ್ಬಂಧಿಸಿ.')
    ),
    NOW()
),
-- Quiz 2: Types of Bank Accounts
(
    '20000000-0000-4000-8000-000000000002'::uuid, '10000000-0000-4000-8000-000000000002'::uuid,
    jsonb_build_array(
        jsonb_build_object('id', 'q2-1', 'question', 'Which account type is best for daily personal savings?', 'options', jsonb_build_array('Current Account', 'Savings Account', 'Fixed Deposit'), 'correctAnswerIndex', 1, 'explanation', 'Savings accounts are designed for daily personal savings with interest earnings.'),
        jsonb_build_object('id', 'q2-2', 'question', 'What is the main difference between a savings account and a current account?', 'options', jsonb_build_array('Savings accounts earn interest, current accounts usually do not', 'Current accounts earn more interest', 'There is no difference'), 'correctAnswerIndex', 0, 'explanation', 'Savings accounts earn interest while current accounts are for business transactions and usually do not earn interest.'),
        jsonb_build_object('id', 'q2-3', 'question', 'What happens if you withdraw a Fixed Deposit before maturity?', 'options', jsonb_build_array('You get bonus interest', 'You may lose some interest as penalty', 'Nothing happens'), 'correctAnswerIndex', 1, 'explanation', 'Early withdrawal of FD usually incurs a penalty and loss of some interest.')
