        jsonb_build_object('id', 'q20-2', 'question', 'ವಿಮೆಗೆ "ಖಾತರಿ ಗಳಿಕೆ" ನೀಡುವವರಿಗೆ ಏನು ಮಾಡಬೇಕು?', 'options', jsonb_build_array('ಕೊಡುಗೆಯನ್ನು ತಕ್ಷಣ ಸ್ವೀಕರಿಸಿ', 'ಎಚ್ಚರಿಕೆಯಿಂದಿರಿ — ವಿಮೆ ಖಾತರಿ ಗಳಿಕೆ ನೀಡುವುದಿಲ್ಲ, ಇದು ವಂಚನೆಯಾಗಿರಬಹುದು', 'ಪರೀಕ್ಷಿಸಲು ಸ್ವಲ್ಪ ಹಣ ಪಾವತಿಸಿ'), 'correctAnswerIndex', 1, 'explanation', 'ವಿಮೆ ಖಾತರಿ ಗಳಿಕೆ ನೀಡುವುದಿಲ್ಲ. ಹೀಗೆ ಹೇಳುವ ಯಾರಾದರೂ ವಂಚನೆ ನಡೆಸುತ್ತಿರಬಹುದು. ಎಚ್ಚರಿಕೆಯಿಂದಿರಿ ಮತ್ತು ವರದಿ ಮಾಡಿ.'),
        jsonb_build_object('id', 'q20-3', 'question', 'ನಿಮ್ಮ ವಿಮಾ ಪ್ರೀಮಿಯಂ ಅನ್ನು ಹೇಗೆ ಪಾವತಿಸಬೇಕು?', 'options', jsonb_build_array('ಏಜೆಂಟ್ ಗೆ ನಗದು', 'ಚೆಕ್ ಅಥವಾ ಆನ್‌ಲೈನ್ ಪಾವತಿಯಂತಹ ಅಧಿಕೃತ ಮಾರ್ಗಗಳ ಮೂಲಕ ಮಾತ್ರ', 'ಫೋನ್ ಮೂಲಕ ನಿಮ್ಮ ಬ್ಯಾಂಕ್ ವಿವರಗಳನ್ನು ಹಂಚಿಕೊಂಡು'), 'correctAnswerIndex', 1, 'explanation', 'ಪ್ರೀಮಿಯಂ ಅನ್ನು ಚೆಕ್ ಅಥವಾ ಆನ್‌ಲೈನ್ ಪಾವತಿಯಂತಹ ಅಧಿಕೃತ ಮಾರ್ಗಗಳ ಮೂಲಕ ಮಾತ್ರ ಪಾವತಿಸಿ. ರಸೀದಿ ಇಲ್ಲದೆ ನಗದು ಪಾವತಿಸಬೇಡಿ.')
